52      public EvaluationOutcome evaluate(EvaluationCommand command) {
53          validate(command);
54          List<RewardView> grants = new ArrayList<>();
55          List<EvaluationOutcome.Skipped> skipped = new ArrayList<>();
56  
57          AccountSnapshot account = accountClient.findAccount(command.accountId()).orElse(null);
58          if (account == null) {
59              skipped.add(new EvaluationOutcome.Skipped(null, null, EligibilityPolicy.ACCOUNT_NOT_FOUND));
60              return new EvaluationOutcome(grants, skipped);
61          }
62  
63          LocalDateTime now = LocalDateTime.now(clock);
64          for (Campaign campaign : campaigns.findActiveAt(now)) {
65              if (rewards.existsByCampaignAndTransaction(campaign.getCampaignId(), command.transactionId())) {
66                  skipped.add(new EvaluationOutcome.Skipped(campaign.getCampaignId(), campaign.getName(),
67                          "ALREADY_EVALUATED"));
68                  continue;
69              }
70              boolean enrolled = enrollments
71                      .findEnrollment(campaign.getCampaignId(), command.cardNumber())
72                      .isPresent();
73              long rewardsOnCard = rewards.countByCampaignAndCard(campaign.getCampaignId(), command.cardNumber());
74              EligibilityPolicy.Evaluation evaluation = EligibilityPolicy.evaluateTransaction(
75                      campaign, account, command.amount(), command.categoryCode(), enrolled,
76                      rewardsOnCard, now);
77              if (!evaluation.eligible()) {
78                  skipped.add(new EvaluationOutcome.Skipped(campaign.getCampaignId(), campaign.getName(),
79                          evaluation.reason()));
80                  continue;
81              }
82  
83              RewardComputation computation = evaluation.reward();
84              try {
85                  campaign.consumeCashback(computation.amount());
86              } catch (BusinessRuleException ex) {
87                  skipped.add(new EvaluationOutcome.Skipped(campaign.getCampaignId(), campaign.getName(),
88                          EligibilityPolicy.BUDGET_EXHAUSTED));
89                  continue;
90              }
91  
92              RewardGrant grant = new RewardGrant(UUID.randomUUID().toString(),
93                      campaign.getCampaignId(), command.transactionId(), command.cardNumber(),
94                      command.accountId(), command.customerId(), computation, now);
95              if (grant.isCashback()) {
96                  try {
97                      accountClient.creditCashback(command.accountId(), grant.getRewardId(),
98                              campaign.getCampaignId(), grant.getRewardAmount());
99                      grant.markGranted(now);
100                  } catch (RemoteServiceException ex) {
101                      grant.markPending("Cashback credit pending: " + ex.getMessage());
102                  }
103              } else {
104                  grant.markGranted(now);
105              }
106              rewards.saveReward(grant);
107              campaigns.saveCampaign(campaign);
108              grants.add(new RewardView(grant, campaign.getName()));
109          }
110          return new EvaluationOutcome(grants, skipped);
111      }
