113      public RewardView fulfill(String rewardId) {
114          RewardGrant grant = rewards.findReward(rewardId)
115                  .orElseThrow(() -> new NotFoundException("REWARD_NOT_FOUND",
116                          "Reward " + rewardId + " not found"));
117          Campaign campaign = campaigns.findCampaign(grant.getCampaignId()).orElse(null);
118  
119          if (!grant.isGranted()) {
120              if (!grant.isCashback()) {
121                  grant.markGranted(LocalDateTime.now(clock));
122              } else {
123                  try {
124                      accountClient.creditCashback(grant.getAccountId(), grant.getRewardId(),
125                              grant.getCampaignId(), grant.getRewardAmount());
126                      grant.markGranted(LocalDateTime.now(clock));
127                  } catch (RemoteServiceException ex) {
128                      grant.markPending(ex.getMessage());
129                      rewards.saveReward(grant);
130                      throw ex;
131                  }
132              }
133              rewards.saveReward(grant);
134          }
135          return new RewardView(grant, campaign == null ? grant.getCampaignId() : campaign.getName());
136      }
