68      /**
69       * 营销返现入账（幂等）：同一 rewardId 重复调用只入账一次。
70       */
71      public Account creditCashback(String accountId, String rewardId, String campaignId, BigDecimal amount) {
72          if (rewardCredits.existsByRewardId(rewardId)) {
73              return getById(accountId);
74          }
75          Account account = getById(accountId);
76          account.applyCashback(amount);
77          Account saved = accounts.saveAccount(account);
78          rewardCredits.saveCredit(new RewardCredit(rewardId, accountId, campaignId, amount,
79                  LocalDateTime.now()));
80          return saved;
81      }
